from ta_ue_plugin_android.ue.android.android_data_transfer_icmp import AndroidDataTransferIcmp


class AtDataTransferIcmp(AndroidDataTransferIcmp):
    """Icmp data transfer class for using specific options on this UE implementation - ping running from Cygwin"""
    UE_SPECIFIC_OPTIONS = {'ping_count': 'n', 'ping_interface_ip': 'S', 'packet_size': 'l'}

    def ping_app_server(self):
        """Ping app server from UE"""
        ue_ip = self._get_ue_ip()
        self.ping_cmd = self._get_ping_cmd(ip_to_ping=self.ping_parameters['ping_host_ip'],
                                           ping_interface_ip=ue_ip,
                                           interface_option_name=self.UE_SPECIFIC_OPTIONS['ping_interface_ip'],
                                           count_option_name=self.UE_SPECIFIC_OPTIONS['ping_count'],
                                           packet_size_option_name=self.UE_SPECIFIC_OPTIONS['packet_size'])
        self.ue_instance._method_proxy('ping_app_server', self.ping_parameters['name'], self.ping_cmd)

    def _get_ue_ip(self):
        interface_name = self._configuration.get('interface_name')
        if not interface_name:
            raise Exception("Please provide interface_name at yaml configuration")
        return self.ue_instance._method_proxy('_get_ip_address_of_interface', interface_name)

    def stop(self):
        """Not implemented"""
        raise NotImplementedError

    def check_data_transfer(self):
        """Not implemented"""
        raise NotImplementedError

    def reset_statistics(self):
        """Not implemented"""
        raise NotImplementedError

    def get_average_throughput(self):
        """Not implemented"""
        raise NotImplementedError

    def get_datagram_loss(self):
        """Not implemented"""
        raise NotImplementedError

    def get_data_transfer_statistics(self):
        """Not implemented"""
        raise NotImplementedError
